    DataClient data(BCall->objectName().toUtf8().constData());
    clt->answerCalledSomeone(data);

    // BOUTON RACCROCHER
    BRefuseCall->hide();
    BAcceptCall->hide();
    for (auto const &butt : listRelations)
        butt->stateHideButton(false);
    // DISABLE ALL BUTTON
